    'faq' => [
        ['q' => 'Une petite école privée a-t-elle vraiment besoin d\'un logiciel ?', 'r' => 'Pas toujours. Une école de quelques classes peut commencer par un échéancier et un site simples, avec un tableur propre. Un logiciel se justifie quand plusieurs personnes saisissent les mêmes informations, que les bulletins sortent en retard ou que l\'état des impayés demande des jours de reconstitution.'],
        ['q' => 'Comment les parents peuvent-ils payer la scolarité par mobile money ?', 'r' => 'Par un agrégateur de paiement relié à l\'outil de l\'école : le parent règle depuis son téléphone, et le versement retombe sur l\'échéance de l\'enfant avec un reçu. Une étude contrôlée, menée dans 50 établissements secondaires privés du Bénin par l\'institut BIGD, teste justement ce mode de paiement ; elle est en cours et n\'a pas encore publié de résultats.'],
        ['q' => 'Que faire des plateformes de l\'État comme Planète au Sénégal ?', 'r' => 'On les garde : l\'école doit s\'y conformer quand le ministère exige la saisie. L\'outil de l\'école prépare des exports propres, de façon à éviter la double saisie, et donne aux familles une page qui explique comment obtenir leur code d\'accès.'],
        ['q' => 'Peut-on utiliser ChatGPT avec les données des élèves ?', 'r' => 'Non, pas dans un outil public. Noms, notes, santé et discipline restent hors des assistants non évalués. L\'IA sert à rédiger des brouillons de communication ou à préparer des supports, sans donnée nominative, et l\'enseignant relit toujours.'],
        ['q' => 'L\'IA peut-elle corriger les copies ou noter les élèves ?', 'r' => 'Elle peut aider à produire un corrigé ou à repérer des erreurs fréquentes, mais la note appartient à l\'enseignant. Le règlement européen sur l\'IA classe parmi les systèmes à haut risque ceux qui évaluent les acquis des élèves, et une décision qui touche un élève doit pouvoir s\'expliquer à sa famille.'],
        ['q' => 'À partir de quel âge peut-on traiter les données d\'un enfant avec son seul consentement ?', 'r' => 'Cela dépend du pays. L\'article 446 du code du numérique béninois fixe 16 ans pour les services de la société de l\'information ; le RGPD fixe 16 ans en principe, avec une baisse possible jusqu\'à 13 ans, et la France a retenu 15 ans. Le choix de la base légale se confirme avec l\'autorité de protection des données du pays.'],
        ['q' => 'Faut-il déclarer le fichier des élèves à une autorité ?', 'r' => 'Dans plusieurs pays, oui. En Côte d\'Ivoire, la loi de 2013 soumet le traitement de données personnelles à une déclaration préalable auprès de l\'ARTCI, et certains traitements à son autorisation. Au Sénégal, la loi de 2008 crée la Commission de protection des données personnelles. Au Bénin, l\'Autorité de protection des données encadre notamment les transferts à l\'étranger. Confirmez la procédure avant de lancer le projet.'],
        ['q' => 'Où héberger les données des élèves ?', 'r' => 'Le choix se fait selon la loi du pays de l\'école, la qualité de la connexion et les garanties du prestataire. Au Bénin, un hébergement hors du pays suppose de regarder l\'article 391 du code du numérique, qui subordonne le transfert au constat, par l\'Autorité, d\'une protection équivalente et à son autorisation préalable. Dans tous les cas, on prévoit une sauvegarde chiffrée et testée, et un contrat qui précise les instructions de l\'école.'],
        ['q' => 'Peut-on envoyer les bulletins aux parents sur WhatsApp ?', 'r' => 'Oui, par messages individuels envoyés avec l\'API officielle de WhatsApp Business, avec le consentement des familles, jamais dans un groupe de parents. Les coûts de messages sont fixés par Meta et se vérifient avant le lancement.'],
        ['q' => 'Combien coûte un site pour une école ?', 'r' => 'Un site vitrine démarre à 300 000 FCFA (environ 457 €) et une landing page à 150 000 FCFA (environ 229 €). Une application de scolarité, de notes et d\'espace parents se chiffre sur devis après le diagnostic.'],
        ['q' => 'Combien de temps faut-il pour digitaliser une école ?', 'r' => 'Cela dépend du projet : on commence par la scolarité et les encaissements, puis les notes et les bulletins, puis l\'espace parents. Le calendrier se cale sur les vacances, pas sur la rentrée.'],
        ['q' => 'Vos formations conviennent-elles aux enseignants ?', 'r' => 'Richard a déjà formé des enseignants et des équipes d\'établissements scolaires. Les programmes portent sur l\'IA pour préparer les cours, la tenue des données de l\'école et la communication avec les familles.'],
        ['q' => 'Intervenez-vous hors du Bénin ?', 'r' => 'Oui, à distance, pour des écoles d\'Afrique francophone et d\'Europe, et sur place au Bénin. Les familles et les écoles hors d\'Afrique règlent par carte bancaire, PayPal ou virement.'],
